def row_u(x1,x2,w1,w2):
 if x1==x2: return 0.0
 if x1>x2:
  return min(w2*(x1-x2)/x1,w1*(x1-x2)/(1-x2))
 return min(w1*(x2-x1)/x2,w2*(x2-x1)/(1-x1))
def uf(t,s):
 return row_u(t,s,1/3,1/6)+row_u(2*t-.5,.5*s,1/6,1/3)
points=[]
for ie in range(201):
 e=1/12+ie/1200
 lo=max(.25,(3*e-.75)/2)
 hi=min(.75,(3*e+.25)/2)
 best=(1.0,None,None)
 for j in range(2001):
  t=lo+(hi-lo)*j/2000
  s=3*e+.25-2*t
  u=uf(t,s)
  if u<best[0]: best=(u,t,s)
 points.append((e,*best))
print('Numerical minimum unfairness for fixed error in Figure 1 example:')
for p in points[::20]: print(p)
# Lower convex hull in error-unfairness plane.
hull=[]
for p in points:
 while len(hull)>1:
  a,b=hull[-2:]
  cross=(b[0]-a[0])*(p[1]-b[1])-(b[1]-a[1])*(p[0]-b[0])
  if cross<=1e-12: hull.pop()
  else: break
 hull.append(p)
print('Lower hull vertices:',len(hull))
print(hull[:15])
